using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class LocalWorkDemandTests
{
    static readonly EntityId Site=new("site:kofu"),Peer=new("person:takeda-nobushige");
    static ContractWorld New(bool enabled=true,bool npc=false,string player="person:shingen")=>NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],player,20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,npc?NewGameNpcRoutine.Policy:null,LocalInspectionFindings.Policy,NewGameWork.Policy,enabled?LocalWorkDemand.Policy:null);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static LocalInspectionNeed Need(WorldSession s)=>LocalWorkDemand.At(s.DiagnosticSnapshot(),Peer,Site,s.Seconds,s.Revision);
    static EntityId Work(WorldSession s,string id="request:demand-first"){
        Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),id),s.Revision).Code);var t=s.DiagnosticSnapshot().Tasks.Last(t=>t.Executor==s.PlayerControl);At(s,s.Seconds+1);var letter=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.KnownBody==null&&m.KnownBody!=t.Id.Value);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,letter.Id,s.Revision).Code);if(t.Kind==TaskKind.VoluntaryRequest)Assert.Equal(ResultCode.Accepted,s.Assent(t.Id,s.PlayerControl,true,s.Revision).Code);return t.Id;
    }
    static WorldSession Complete(){var s=new WorldSession(New());Work(s);At(s,8);return s;}
    [Fact] public void MissingKnownRecordsCreatesExistingInspection(){var w=New();var n=LocalWorkDemand.At(w,Peer,Site,0,0);Assert.True(n.Needed);Assert.Equal("missing-record",n.Reason);Assert.NotEmpty(n.MissingEdges);Assert.Equal(ActionKind.Inspect,NewGameWorld.LocalWork(w,"request:need").Action);}
    [Fact] public void UnknownWorldBlockCannotChangeNeed(){var a=New();var b=ContractJson.Copy(a);b.Couriers=b.Couriers! with{Conditions=[new RoadCondition(0,BranchRoutes.GraphEdges(a).First(e=>e.From=="kofu"||e.To=="kofu").Id,true)]};Assert.Equal(ContractJson.Write(LocalWorkDemand.At(a,Peer,Site,0,0)),ContractJson.Write(LocalWorkDemand.At(b,Peer,Site,0,0)));}
    [Fact] public void SameSecondSecondRequestIsRejected(){var s=new WorldSession(New());var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:first");Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.False(Need(s).Needed);Assert.Equal("await-report",Need(s).Reason);Assert.Equal(ResultCode.InvalidInput,s.Submit(i with{RequestId=new("request:duplicate")},s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void CurrentReceivedRecordsSuppressAnotherPaidJob(){var s=Complete();Assert.False(Need(s).Needed);Assert.Equal("records-current",Need(s).Reason);Assert.Throws<InvalidDataException>(()=>NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:again"));}
    [Fact] public void SourceObservationAgeControlsExactRenewalBoundary(){var s=Complete();long observed=s.DiagnosticSnapshot().Messaging.Messages.Where(m=>m.Kind=="route-observation").Max(m=>m.CreatedAt);At(s,observed+LocalWorkDemand.RecordAge-1);Assert.False(Need(s).Needed);At(s,observed+LocalWorkDemand.RecordAge);Assert.True(Need(s).Needed);Assert.Equal("old-record",Need(s).Reason);Assert.NotEmpty(Need(s).StaleEdges);}
    [Fact] public void StaleNeedCanIssueOneNewTaskWithoutInstantPayment(){var s=Complete();At(s,3607);Assert.True(Need(s).Needed);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:renewed"),s.Revision).Code);Assert.False(Need(s).Needed);Assert.Empty(s.DiagnosticSnapshot().Transfers);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact] public void SameSecondReceiptDoesNotRewritePriorDecision(){var s=new WorldSession(New());Work(s);At(s,6);Assert.Equal("await-report",Need(s).Reason);At(s,7);Assert.Equal("records-current",Need(s).Reason);_ = new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact] public void LostRoadPaperRemainsPendingAfterCompletionReport(){var s=new WorldSession(New());Work(s);At(s,5);var paper=s.DiagnosticSnapshot().Outbox.First(o=>o.Kind=="route-observation");s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,paper.Id.Value));At(s,20);Assert.Equal("await-report",Need(s).Reason);Assert.False(Need(s).Needed);Assert.NotEmpty(Need(s).MissingEdges);}
    [Fact] public void RecoveredPaperResolvesNeedThroughRealReceipt(){var s=new WorldSession(New());Work(s);At(s,5);var paper=s.DiagnosticSnapshot().Outbox.First(o=>o.Kind=="route-observation");s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,paper.Id.Value));At(s,9);Assert.Equal(ResultCode.Accepted,s.RetryCourier(s.PlayerControl,paper.Id.Value,"kofu",s.Seconds+1,s.Revision).Code);At(s,12);Assert.Equal("records-current",Need(s).Reason);}
    [Fact] public void KnownFailedTaskAllowsNewMissingRecordJob(){var s=new WorldSession(New());var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:declined");s.Submit(i,s.Revision);At(s,1);var t=s.DiagnosticSnapshot().Tasks.Last();var m=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.KnownBody==null);s.Open(s.PlayerControl,m.Id,s.Revision);s.Assent(t.Id,s.PlayerControl,false,s.Revision);At(s,8);Assert.True(Need(s).Needed);Assert.Equal("missing-record",Need(s).Reason);}
    [Fact] public void IssuedWorkIsNotDuplicatedByNpcSelfInspection(){var s=new WorldSession(New(npc:true));Work(s);At(s,9);var w=s.DiagnosticSnapshot();Assert.Single(w.Requests,r=>r.Intent.Actor==Peer&&r.Intent.Action==ActionKind.Inspect);Assert.Contains(w.NpcWork!.Decisions,d=>d.Actor==Peer&&d.Reason=="await-own-report");Assert.False(Need(s).Needed);}
    [Fact] public void NpcOwnRecordsAlsoSatisfyLocalNeed(){var s=new WorldSession(New(npc:true));At(s,9);Assert.Equal("records-current",Need(s).Reason);Assert.False(Need(s).Needed);}
    [Fact] public void HiddenNewBlockDoesNotCreateAJobUntilKnownOrStale(){var s=Complete();var a=s.DiagnosticSnapshot();var b=ContractJson.Copy(a);b.Couriers=b.Couriers! with{Conditions=[new RoadCondition(9,BranchRoutes.GraphEdges(a).First(e=>e.From=="kofu"||e.To=="kofu").Id,true)]};Assert.Equal(ContractJson.Write(LocalWorkDemand.At(a,Peer,Site,10,a.CommitSequence)),ContractJson.Write(LocalWorkDemand.At(b,Peer,Site,10,b.CommitSequence)));}
    [Fact] public void OwnInspectionAndMilitaryRemainIndependent(){var s=Complete();Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:own-check"),s.Revision).Code);Assert.True(NewGameMilitary.ViewWithAuthority(s.DiagnosticSnapshot()).CanRequest);}
    [Fact] public void LegacyPolicyRetainsRepeatedLocalWork(){var s=new WorldSession(New(false));Work(s);At(s,8);Assert.Equal("legacy-unrestricted",Need(s).Reason);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:legacy-repeat"),s.Revision).Code);Assert.DoesNotContain("DemandPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewGame)));}
    [Fact] public void UnknownDemandPolicyIsRejected(){var w=New();w.NewGame=w.NewGame! with{DemandPolicy="unknown"};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void DemandCannotExistWithoutWorkPolicy(){Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",demandPolicy:LocalWorkDemand.Policy));}
    [Fact] public void UnmappedSiteCannotCreateDemand(){var w=New();Assert.False(LocalWorkDemand.At(w,Peer,new("site:iki"),0,0).Needed);Assert.Equal("unmapped",LocalWorkDemand.At(w,Peer,new("site:iki"),0,0).Reason);}
    [Fact] public void NewCampaignProfilePinsDemandAndLegacyOmitsIt(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"demand-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy,NewGameWork.Policy,LocalWorkDemand.Policy);Assert.Equal(LocalWorkDemand.Policy,store.Read(p.Instance).DemandPolicy);Assert.Equal(p.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(p)));var old=store.New(p.Setup,[],p.Selected,42,historicalCatalog:HistoricalStartCatalog.Current);Assert.Null(old.DemandPolicy);Assert.DoesNotContain("DemandPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(old)));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(3607)]public void RestorePreservesNeedAndSameFuture(int at){var s=new WorldSession(New());if(at>0)Work(s);At(s,at);s.SetPaused(true);var w=s.DiagnosticSnapshot();var before=ContractJson.Write(Need(s));var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"demand-save-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(before,ContractJson.Write(Need(host.Current)));At(s,3610);At(host.Current,3610);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(Need(s)),ContractJson.Write(Need(host.Current)));}
}
